SELECT v.version || ' — выпуск закрыт, а выжимки версии нет' AS detail FROM version_state v WHERE v.project_id = $1 AND v.state = 'closed' AND NOT EXISTS (SELECT 1 FROM project_runs_log r WHERE r.project_id = v.project_id AND r.is_version AND r.id = v.version) UNION ALL SELECT r.id || ' — выжимка версии называет ' || r.sections || ' разделов, а этапных выжимок ' || (SELECT count(*) FROM project_runs_log m WHERE m.project_id = r.project_id AND m.is_milestone) FROM project_runs_log r JOIN version_state v ON v.project_id = r.project_id AND v.version = r.id AND v.state = 'closed' WHERE r.project_id = $1 AND r.is_version AND r.sections <> (SELECT count(*) FROM project_runs_log m WHERE m.project_id = r.project_id AND m.is_milestone) ORDER BY 1
